/bin/zsh -lc "python3 -B - <<'PY'
from pathlib import Path
from contextlib import closing
import ast, sqlite3, tempfile, json
import vault

source=Path('vault.py').read_text()
for node in ast.parse(source).body:
    if isinstance(node, ast.FunctionDef):
        print('location', node.name, node.lineno, node.end_lineno)
needles=('projection.deserialize', 'projection.setconfig', 'for table in _COLUMNS:', 'if table in rowid_tables:', \"f'DELETE FROM {table}'\", \"kind not in\", 'con.execute(\\'DELETE FROM \\'+', 'con.setconfig', '_apply_auxiliary(con, before, after)')
for number,line in enumerate(source.splitlines(),1):
    if any(needle in line for needle in needles):
        print(f'{number}: {line.strip()}')

with tempfile.TemporaryDirectory(dir=Path.cwd()) as tmp:
    path=Path(tmp)/'bounds.db'
    vault.init_db(path)
    with closing(sqlite3.connect(path)) as con,con:
        con.executescript(\"INSERT INTO accounts VALUES('one','a',100),('one','b',0);\")
    for entry,args in [('balance', ('one','missing')),('balance', ('one','\\ud800')),('transfer', ('one','a','b',10,'\\ud800'))]:
        try:
            result=getattr(vault,entry)(path,*args)
        except Exception as exc:
            result={'type':type(exc).__name__,'message':str(exc)}
        print(json.dumps({'probe':'text_boundaries','entry':entry,'args':args,'outcome':result}))
    with closing(sqlite3.connect(path)) as con:
        print('text_boundary_final_rows', {table:con.execute('SELECT * FROM '+table).fetchall() for table in ('accounts','transfers','audit')})

    for engine in ('candidate','native'):
        path=Path(tmp)/(engine+'.db')
        vault.init_db(path)
        with closing(sqlite3.connect(path)) as con,con:
            con.executescript('''INSERT INTO accounts VALUES('one','a',100),('one','b',0);
                CREATE VIRTUAL TABLE docs USING fts5(body);
                CREATE VIRTUAL TABLE vocabulary USING fts5vocab(docs,'row');
                CREATE TRIGGER add_document AFTER INSERT ON audit BEGIN
                  INSERT INTO docs(body) VALUES('transfer committed');
                END;''')
        try:
            if engine=='candidate':
                result=vault.transfer(path,'one','a','b',10,'k')
            else:
                with closing(sqlite3.connect(path)) as con,con:
                    con.execute(\"UPDATE accounts SET balance=balance-10 WHERE tenant='one' AND name='a'\")
                    con.execute(\"UPDATE accounts SET balance=balance+10 WHERE tenant='one' AND name='b'\")
                    con.execute(\"INSERT INTO transfers VALUES ('one','k','a','b',10)\")
                    con.execute(\"INSERT INTO audit VALUES ('one','k','a','b',10)\")
                result='committed'
        except Exception as exc:
            result={'type':type(exc).__name__,'message':str(exc)}
        with closing(sqlite3.connect(path)) as con:
            print(json.dumps({'probe':'auxiliary_fts_vocab','engine':engine,'result':result,'balances':con.execute('SELECT balance FROM accounts').fetchall(),'vocabulary':con.execute('SELECT * FROM vocabulary').fetchall()}))
PY"

